    /// <summary>Все ключи и русские шаблоны (тест ресурсов).</summary>
    public static IReadOnlyDictionary<string, string> All => s_templates;

    /// <exception cref="KeyNotFoundException">Ключа нет в каталоге.</exception>
    public static string Template(string key) => s_templates.TryGetValue(key, out var t) ? t
        : throw new KeyNotFoundException($"Шаблона диагностики «{key}» нет в каталоге.");

    public static bool TryTemplate(string key, out string template) => s_templates.TryGetValue(key, out template!);
